const S={events:[],event:null,kind:'photo',layout:'strip',frame:'backstage',videoDesign:'livecut',motionDesign:'flipbook',payment:null,filter:'Original',template:'Memories',caption:'',sticker:'✦',poses:4,delay:3,mirror:true,facing:'user',media:[],stream:null,recording:false,busy:false,light:false,music:'original',keepAudio:true,consent:false,tab:'Ringkasan',dash:null,room:null,filmDuration:60,stage:1,cameraReady:false};
const ui={frames:Object.fromEntries(PixDesign.catalog.map(d=>[d.id,[d.bg,d.ink]])),filters:{Original:'none','B&W':'grayscale(1)',Vintage:'sepia(.35) saturate(.8) contrast(.95)',Glow:'brightness(1.07) saturate(1.12)'}};
