async function api(url,body,method){const controller=new AbortController(),deadline=setTimeout(()=>controller.abort(),15000);let res;try{res=await fetch(url,{signal:controller.signal,method:method||(body?'POST':'GET'),credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined})}finally{clearTimeout(deadline)}let data;try{data=await res.json()}catch{throw new Error('Layanan tidak merespons. Muat ulang halaman.')}if(!res.ok)throw Object.assign(new Error(data.error||'Permintaan gagal.'),{status:res.status});return data}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function info(title,body){$('#info-content').innerHTML=`<div class="info-top"><span class="eyebrow">PixBooth</span><button class="close-button" data-a="close-info" aria-label="Tutup">×</button></div><h2>${title}</h2>${body}`;if(!$('#info').open)$('#info').showModal()}
function footer(){return `<footer>${brand()}<span>Little moments. Lasting memories.</span><span>Versi pengembangan lokal · Belum untuk transaksi publik</span></footer>`}
function stopStream(){S.cameraReady=false;S.cameraToken=(S.cameraToken||0)+1;if(S.recorder?.state==='recording')S.recorder.stop();S.stream?.getTracks().forEach(t=>t.stop());S.stream=null;S.recording=false;clearInterval(S.recordTicker)}
function cleanup(){S.audio?.pause();S.media.forEach(m=>m.element.pause?.());cancelAnimationFrame(previewRaf);clearTimeout(jobPoll);stopStream();if(S.room)leaveRoom()}
function nav(url){cleanup();history.pushState({},'',url);currentPath=location.pathname;route();window.scrollTo(0,0)}
window.addEventListener('popstate',()=>{cleanup();currentPath=location.pathname;route()});
async function route(){try{S.events=(await api('/api/events')).events;if(currentPath==='/'){const sub=location.hostname.split('.')[0];const matched=S.events.find(e=>e.id===sub);if(matched){S.event=matched;currentPath='/e/'+matched.id;eventPage();if(new URLSearchParams(location.search).has('room'))openLdr();return}if(['admin','mitra','keuangan'].includes(sub)){currentPath='/'+sub;return loadPortal()}return marketing();}if(currentPath.startsWith('/e/')){const incoming=S.events.find(e=>e.id===currentPath.split('/')[2]);if(S.event&&incoming&&S.event.id!==incoming.id){S.media.forEach(m=>URL.revokeObjectURL(m.url));S.media=[];S.kind='photo';S.stage=1;S.payment=null;S.consent=false;S.caption=''}S.event=incoming;if(!S.event)return missing();eventPage();if(new URLSearchParams(location.search).has('room'))openLdr();return}if(['/admin','/mitra','/keuangan'].includes(currentPath))return loadPortal();if(currentPath==='/hasil')return restoreResult();missing()}catch(e){app.innerHTML=`<div class="page"><h1>Belum bisa terhubung.</h1><p class="muted">${esc(e.message)}</p><button class="primary" data-a="reload">Coba lagi</button></div>`}}
function missing(){app.innerHTML=`<div class="page">${brand()}<h1>Halaman tidak tersedia.</h1><p class="muted">Acara mungkin belum aktif atau alamat tidak sesuai.</p><a class="primary" href="/">Kembali ke beranda</a></div>`}
function marketing(){document.body.className='';app.innerHTML=`<header class="header">${brand()}<nav class="topnav"><a href="#pengalaman">Lihat pengalaman</a><a href="#cara">Cara kerja</a><a class="pill-link" href="#kerjasama">Untuk acaramu ↗</a></nav></header><main class="marketing"><section class="marketing-hero"><div><span class="eyebrow">YOUR MOMENTS, BEAUTIFULLY KEPT</span><h1>Datang untuk<br>momennya.<br><em>Pulang bawa cerita.</em></h1><p>Photobox, foto bergerak, dan video kenangan. Satu scan untuk membawa pulang pengalaman yang terasa kamu.</p><div class="studio-actions"><a class="primary" href="#pengalaman">Coba pengalamannya ↗</a><a class="secondary" href="#kerjasama">Jadi mitra</a></div><p class="micro">Tanpa instal aplikasi · Kamera langsung · Hasil siap dibagikan</p></div><div class="marketing-art"><div class="back-card"><div class="back-title">little moments,<br>big feelings.</div></div><div class="story concert"><div class="concert-art"><div class="beam"></div><div class="beam two"></div><div class="stage"></div><div class="crowd"></div></div><div class="story-tag"><span>pixbooth.</span><span>YOUR STORY</span></div><div class="story-copy"><small>MAKE IT A MEMORY</small><strong>I WAS<br>HERE.</strong><p>A MOMENT TO KEEP</p></div></div><div class="float-label top">✦ Foto. Video. <b>Perasaan.</b></div><div class="float-label bottom">♥ Dibuat dari momenmu sendiri.</div></div></section><section class="section-gap" id="pengalaman"><span class="eyebrow">ONE PLATFORM, MANY FEELINGS</span><h2>Setiap tempat punya ceritanya.</h2><p class="muted">Jelajahi contoh konser, wedding, lari, wisata, dan komunitas. Setiap acara memiliki halaman dan suasananya sendiri.</p><div class="event-examples">${[...S.events].sort((a,b)=>(['scream-or-dance','preston-fest','stride-5k'].includes(b.id)?1:0)-(['scream-or-dance','preston-fest','stride-5k'].includes(a.id)?1:0)).map(e=>`<a class="example" href="/e/${e.id}" data-nav><div class="example-cover ${e.type} ${e.id==='scream-or-dance'?'sod-cover':e.id==='preston-fest'?'preston-cover':''}"><span class="eyebrow" style="color:inherit">${e.type==='concert'?'TURN UP THE MEMORIES':e.type==='tourism'?'YOUR LITTLE ESCAPE':e.type==='running'?'EVERY STEP, A STORY':'A DAY TO REMEMBER'}</span><div class="event-logo large">${e.id==='scream-or-dance'?`<img src="/sod-assets/logo.png?v=original2" alt="Logo Scream or Dance" style="width:100%;height:auto">`:e.id==='preston-fest'?`<img src="/preston-assets/logo.png" alt="Logo Preston Fest" style="width:100%;height:auto">`:e.logoURL?.startsWith("/running-assets/")?`<img src="/running-assets/logo-white.png" alt="Logo ${esc(e.name)}" style="width:100%;height:auto">`:PixExperience.logoSVG(e)}</div></div><div class="example-body"><h3>${esc(e.name)}</h3><b>${e.type==='concert'?'Untuk malam yang tak terlupa':e.type==='tourism'?'Bawa pulang perjalananmu':e.type==='running'?'Finish membawa cerita':'Rayakan cinta, simpan ceritanya'}</b><span>↗</span><p>${esc(e.location)} · ${['scream-or-dance','preston-fest','stride-5k'].includes(e.id)?(e.id==='scream-or-dance'?'12':'16')+' template · 1–4 foto':'Contoh pengalaman'}</p>${['scream-or-dance','preston-fest','stride-5k'].includes(e.id)?`<div class="home-frame-previews">${PixFestival.catalog.filter(d=>d.eventId===e.id).slice(0,3).map(d=>d.id).map(id=>`<img src="/festival-preview/${id}-contoh.png" alt="Contoh frame ${esc(e.name)}" loading="lazy">`).join('')}</div>`:''}</div></a>`).join('')}</div></section><section class="section-gap" id="cara"><span class="eyebrow">A LITTLE EFFORT, A LOT OF MEMORIES</span><h2>Masuk momen. Keluar kenangan.</h2><div class="benefit-grid"><article><span>01</span><h3>Scan & masuk</h3><p>QR membawamu langsung ke pengalaman acara. Tidak perlu mencari menu atau membuat akun.</p></article><article><span>02</span><h3>Rekam, foto, atau unggah</h3><p>Pose seperti di photobox, kumpulkan klip, atau foto bersama seseorang dari jauh lewat ruang LDR.</p></article><article><span>03</span><h3>Simpan & bagikan</h3><p>Foto resolusi tinggi dan video otomatis dengan identitas acara. Siap menemani Story-mu.</p></article></div></section><section class="section-gap contact-section" id="kerjasama"><div><span class="eyebrow">LET'S MAKE SOMETHING MEMORABLE</span><h2>Acara selesai.<br>Ceritanya terus berjalan.</h2><p class="muted">Buat pengalaman dengan desain, bingkai, kuota, dan paket yang sesuai acaramu. Tersedia konsep ditanggung penyelenggara maupun gabungan.</p><div class="tag-row"><span class="badge">WISATA</span><span class="badge">KONSER</span><span class="badge">WEDDING</span><span class="badge">LARI & KOMUNITAS</span></div><p class="micro">Formulir tersimpan di aplikasi lokal ini. Tidak mengirim email atau WhatsApp.</p></div><form class="stack-form" id="inquiry-form"><label for="inq-name">Nama / perusahaan</label><input id="inq-name" name="name" required maxlength="100" placeholder="Nama kamu atau perusahaan"><label for="inq-contact">Email / nomor kontak</label><input id="inq-contact" name="contact" required maxlength="150" placeholder="Kontak yang bisa dihubungi"><label for="inq-type">Jenis kebutuhan</label><select id="inq-type" name="type"><option>Tempat wisata</option><option>Konser / festival</option><option>Wedding</option><option>Lari / olahraga</option><option>Acara lainnya</option></select><label for="inq-note">Ceritakan rencanamu</label><textarea id="inq-note" name="note" maxlength="2000" placeholder="Tanggal, perkiraan tamu, dan kebutuhanmu…"></textarea><button class="primary" type="submit">Ajukan kerja sama ↗</button></form></section></main>${footer()}`}
function eventHeader(){const e=S.event;return `<header class="event-header"><div class="event-brand event-logo">${PixExperience.logoSVG(e)}</div><small>${esc([e.location,e.date].filter(Boolean).join(" · "))}</small><span class="brand">pixbooth<span>.</span></span></header>`}
function eventPage(){if(!PixExperience.forType(S.event.type).some(d=>d.id===S.videoDesign))S.videoDesign=PixExperience.forType(S.event.type)[0].id;if(!PixDesign.forEvent(S.event).some(d=>d.id===S.frame))S.frame=PixDesign.forEvent(S.event)[0].id;document.title=S.event.name+' — PixBooth';document.body.className='event-app '+S.event.type;const e=S.event;app.innerHTML=`${eventHeader()}<main class="event-shell"><section class="event-welcome"><div><span class="eyebrow">MAKE THIS MOMENT YOURS</span><h1>${esc(e.headline)}</h1><p>Foto langsung, kumpulkan klip, atau ajak seseorang yang jauh. Kenangannya kita rangkai.</p></div><div class="event-promo">✦ ${e.plan==='sponsored'?'Ditanggung penyelenggara':e.plan==='hybrid'?'Foto gratis · Video '+money(e.price):'Foto '+money(Math.round(e.price*.4))+' · Video '+money(e.price)}<br>${e.sponsor?'Dipersembahkan oleh '+esc(e.sponsor):'Kenangan khusus untukmu'}</div></section><div class="workspace"><section class="capture-panel"><div class="capture-top"><div class="segmented">${[['photo','Foto'],['motion','GIF / Motion'],['video','Film 60 detik']].map(([k,n])=>`<button data-kind="${k}" class="${S.kind===k?'active':''}">${n}</button>`).join('')}</div><small id="camera-state">Kamera belum aktif</small></div><div class="camera-box" id="camera-box"><div class="camera-empty"><span class="camera-symbol">◎</span><h2>Siap untuk momenmu?</h2><p>Kamera hanya aktif setelah kamu memilih membukanya. Kamu bisa mengambil foto atau merekam klip langsung.</p><button class="primary" data-a="open-camera">Buka kamera ↗</button></div></div><div class="camera-actions"><button class="icon-button" data-a="flip">↻ Balik kamera</button><button class="shutter" data-a="capture" aria-label="${S.kind==='video'?'Rekam video':'Ambil foto'}">${S.kind==='video'?'●':'◎'}</button><button class="icon-button" data-a="light">☀ Cahaya layar</button></div><div class="capture-footer">${S.kind==='video'?'Rekam 3–5 klip, masing-masing maksimal 10 detik. Kami susun menjadi film 60 detik. Jika bahan sedikit, beberapa momen dipakai ulang.':'Ambil '+S.poses+' pose dengan hitungan mundur. Kamu juga bisa mengganti foto satu per satu.'}</div><div class="media-tray" id="media-tray"></div>${e.allowUpload?`<div style="padding:0 18px 17px"><button class="secondary full-width" data-a="upload">↑ Pilih ${S.kind==='video'?'video':'foto'} dari galeri</button><input class="file-input" id="file-input" type="file" accept="${S.kind==='video'?'video/mp4,video/webm,video/quicktime':'image/jpeg,image/png,image/webp'}" multiple></div>`:''}</section><aside class="design-panel"><h2>02 / Pilih cerita visualmu</h2><canvas class="result-preview" id="composition" width="540" height="960" aria-label="Pratinjau desain foto atau video"></canvas><div class="field-title">Desain khusus ${esc(S.event.name)}<span>Nama acara otomatis</span></div>${designPicker()}<div class="design-description" id="design-description">${activeDesigns().find(d=>d.id===activeDesign()).tag}</div>${S.kind==='video'?'<div class="film-timeline"><b>60 detik / 12 babak</b><p>Opening → momen utama → split screen → detail → highlight → closing</p><small>Perubahan framing, zoom, lapisan grafis, dan audio otomatis.</small></div>':''}<div class="field-title">Filter</div><div class="chips">${Object.keys(ui.filters).map(f=>`<button data-filter="${f}" aria-pressed="${S.filter===f}" class="${S.filter===f?'active':''}">${f}</button>`).join('')}</div><div class="field-title"><label for="caption">Caption pendek</label><span>${S.sticker}</span></div><input type="text" id="caption" maxlength="45" value="${esc(S.caption)}" placeholder="Hari yang ingin diulang."><div class="chips" style="margin-top:9px">${['✦','♡','✧','☺',''].map(t=>`<button data-sticker="${t}" class="${S.sticker===t?'active':''}">${t||'Tanpa stiker'}</button>`).join('')}</div>${S.kind==='photo'?`<div class="small-controls"><label>Pose <select id="poses"><option ${S.poses===4?'selected':''}>4</option><option ${S.poses===3?'selected':''}>3</option><option ${S.poses===1?'selected':''}>1</option></select></label><label>Timer <select id="delay"><option value="3" ${S.delay===3?'selected':''}>3 dtk</option><option value="5" ${S.delay===5?'selected':''}>5 dtk</option></select></label></div>`:`<div class="field-title"><label for="music">Audio</label><button class="text-button" data-a="preview-music">Dengarkan ♫</button></div><select id="music"><option value="original" ${S.music==='original'?'selected':''}>PixBooth Original · musik contoh 60 detik</option><option value="none" ${S.music==='none'?'selected':''}>Tanpa musik tambahan</option></select>${e.type==='concert'?'<button class="text-button" data-a="perunggu-reference">♫ Referensi: Perunggu — 33x ↗</button>':''}<div class="small-controls"><label><input id="keep-audio" type="checkbox" ${S.keepAudio?'checked':''}>Pertahankan suara rekaman</label></div>`}<label class="privacy-consent"><input id="consent" type="checkbox" ${S.consent?'checked':''}><span>Saya setuju media dikirim ke server aplikasi ini untuk membuat hasil dan disimpan selama ${e.retention} jam. Konten tidak otomatis dipublikasikan.</span></label><button class="primary full-width" data-a="generate" ${S.busy?'disabled':''}>${S.kind==='photo'?'Buat foto Story':S.kind==='motion'?'Buat GIF & Motion':'Buat film 60 detik'} ↗</button><p class="micro" style="color:#9c87ac">${S.kind==='photo'?'PNG 1080 × 1920':S.kind==='motion'?'GIF + MP4 vertikal':'MP4 60 detik · 1080 × 1920'} · ${S.media.length} bahan dipilih</p><button class="ldr-toggle" data-a="ldr"><div><b>♡ LDR Photobox</b><small>Jauh tempatnya. Tetap satu frame.</small></div><span>↗</span></button></aside></div><div class="event-bottom"><span>Kontenmu tidak otomatis masuk galeri publik.</span><span>Prototype · Checkout simulasi, tanpa uang sungguhan.</span></div><section class="event-details"><div><span class="eyebrow">TENTANG PENGALAMAN INI</span><h2>${esc(e.name)}</h2><p>${esc(e.description)}</p></div><dl><dt>Penyelenggara</dt><dd>${esc(e.organizer)}</dd><dt>Lokasi & tanggal</dt><dd>${esc([e.location,e.date].filter(Boolean).join(" · "))}</dd><dt>Akses</dt><dd>${esc(e.schedule)}</dd><dt>Paket</dt><dd>${e.plan==='sponsored'?'Ditanggung penyelenggara':e.plan==='hybrid'?'Foto gratis; GIF dan film berbayar':'Pengunjung membayar per hasil'}</dd><dt>Privasi & bantuan</dt><dd>Media privat · simpan ${e.retention} jam · hapus otomatis setelah kedaluwarsa. <a href="mailto:${esc(e.contact)}">${esc(e.contact)}</a> (kontak contoh)</dd></dl></section></main>`;renderTray();refreshDesignPreviews();startPreview();if(S.stream)mountCamera().catch(cameraError)}
function drawCover(ctx,source,x,y,w,h,mirror=false){const sw=source.videoWidth||source.naturalWidth||source.width,sh=source.videoHeight||source.naturalHeight||source.height;if(!sw||!sh)return;const scale=Math.max(w/sw,h/sh),cw=w/scale,ch=h/scale;ctx.save();if(mirror){ctx.translate(x+w,y);ctx.scale(-1,1);x=0;y=0}ctx.drawImage(source,(sw-cw)/2,(sh-ch)/2,cw,ch,x,y,w,h);ctx.restore()}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function placeholder(ctx,x,y,w,h,i){const g=ctx.createLinearGradient(x,y,x+w,y+h);if(S.event.type==='tourism'){g.addColorStop(0,'#99b9ae');g.addColorStop(1,'#38534b')}else if(S.event.type==='wedding'){g.addColorStop(0,'#e5d8c2');g.addColorStop(1,'#ad9680')}else{g.addColorStop(0,'#55466d');g.addColorStop(1,'#c699ad')}ctx.fillStyle=g;ctx.fillRect(x,y,w,h);ctx.fillStyle='#ffffff55';ctx.font=`${Math.min(w,h)*.33}px Georgia`;ctx.textAlign='center';ctx.fillText(['✦','♡','✧','☺'][i%4],x+w/2,y+h*.6)}
function activeDesigns(){return S.kind==='photo'?PixDesign.forEvent(S.event):S.kind==='motion'?PixExperience.motions:PixExperience.forType(S.event.type)}
function activeDesign(){return S.kind==='photo'?S.frame:S.kind==='motion'?S.motionDesign:S.videoDesign}
function paint(canvas,overlay=false){if(!canvas||!S.event)return;const options={event:S.event,design:activeDesign(),kind:S.kind,media:S.media.map(m=>m.element),filter:ui.filters[S.filter],framing:S.media.map(m=>m.framing),caption:S.caption,sticker:S.sticker,poses:S.poses,scene:overlay?0:Math.floor(performance.now()/1000)%12,overlay};if(S.kind==='photo')PixDesign.render(canvas,options);else PixExperience.render(canvas,options)}
function designPicker(){return '<div class="design-picker">'+activeDesigns().map(d=>`<button class="design-option ${activeDesign()===d.id?'active':''}" data-experience="${d.id}" aria-pressed="${activeDesign()===d.id}"><canvas width="216" height="384" data-design-preview="${d.id}" aria-label="Contoh desain ${d.name}"></canvas><b>${d.name}</b><small>${d.tag}</small></button>`).join('')+'</div>'}
function refreshDesignPreviews(){document.querySelectorAll('[data-design-preview]').forEach(c=>{const o={event:S.event,design:c.dataset.designPreview,kind:S.kind,media:S.media.map(m=>m.element),filter:ui.filters[S.filter],framing:S.media.map(m=>m.framing),poses:S.poses,caption:S.caption,sticker:S.sticker};(S.kind==='photo'?PixDesign:PixExperience).render(c,o)})}
function startPreview(){cancelAnimationFrame(previewRaf);let last=0;const loop=(now=0)=>{if(!$('#composition'))return;if(now-last>200||!last){paint($('#composition'));last=now}previewRaf=requestAnimationFrame(loop)};loop()}
function renderTray(){const tray=$('#media-tray');if(!tray)return;tray.innerHTML=S.media.length?S.media.map((m,i)=>`<div class="tray-item">${m.type==='video'?`<video src="${m.url}" muted playsinline></video>`:`<img src="${m.url}" alt="Pose ${i+1}">`}<button data-remove="${i}" aria-label="Hapus bahan ${i+1}">×</button><span>${m.type==='video'?m.duration.toFixed(1)+'s':i+1}</span></div>`).join(''):'<div class="tray-empty">Hasil foto atau klipmu akan muncul di sini.</div>';const hint=$('.design-panel .micro');if(hint)hint.textContent=(S.kind==='photo'?'PNG 1080 × 1920':S.kind==='motion'?'GIF + MP4 vertikal':'MP4 60 detik · 1080 × 1920')+' · '+S.media.length+' bahan dipilih'}
async function addMedia(blob,type,knownDuration=0){if(S.media.length>=5)throw new Error('Maksimal lima bahan. Hapus salah satu untuk mengganti.');const url=URL.createObjectURL(blob),element=document.createElement(type==='video'?'video':'img');let duration=0;try{await new Promise((resolve,reject)=>{const t=setTimeout(()=>reject(new Error('Media terlalu lama dibaca.')),12000);element[type==='video'?'onloadedmetadata':'onload']=()=>{const finish=()=>{clearTimeout(t);if(type==='video'){duration=knownDuration||element.duration;if(!Number.isFinite(duration)||duration>15.2)return reject(new Error('Maksimal 15 detik per klip. Potong melalui galeri sebelum mengunggah.'))}resolve()};if(type==='video'&&!knownDuration&&!Number.isFinite(element.duration)){element.ontimeupdate=()=>{if(Number.isFinite(element.duration)){element.ontimeupdate=null;element.currentTime=0;finish()}};element.currentTime=1e9}else finish()};element.onerror=()=>{clearTimeout(t);reject(new Error('File tidak dapat dibaca. Pilih file lain.'))};element.src=url});if(type==='video'){element.muted=true;element.loop=true;element.playsInline=true;if(!S.media.length)await element.play().catch(()=>{})}S.media.push({blob,type,url,element,duration});renderTray();refreshDesignPreviews()}catch(e){URL.revokeObjectURL(url);throw e}}
async function openCamera(withAudio=S.kind==='video'){
 if(S.cameraOpening)return;S.cameraOpening=true;stopStream();const token=S.cameraToken;
 try{setCameraStatus('Membuka kamera…');const stream=await PixCamera.request(navigator.mediaDevices,S.facing,withAudio);if(token!==S.cameraToken){stream.getTracks().forEach(t=>t.stop());return}S.stream=stream;await PixCamera.naturalZoom(stream);await mountCamera();if(S.cameraReady)trackMetric('start')}
 catch(e){stopStream();cameraError(e)}finally{S.cameraOpening=false}
}
function setCameraStatus(label){const el=$('#camera-state');if(el)el.textContent=label}
function cameraError(e){const messages={NotAllowedError:'Izin kamera atau mikrofon belum diberikan. Buka izin situs di Safari/Chrome, lalu coba lagi.',NotFoundError:'Kamera tidak ditemukan. Gunakan perangkat berkamera.',NotReadableError:'Kamera sedang dipakai aplikasi lain. Tutup aplikasi tersebut, lalu coba lagi.'};const message=messages[e.name]||e.message;setCameraStatus('Kamera belum siap');const box=$('#camera-box');if(box)box.innerHTML=`<div class="camera-empty" role="alert"><span class="camera-symbol">◎</span><h2>Kamera belum siap</h2><p>${esc(message)}</p><button class="primary" data-a="open-camera">Coba buka kamera</button>${S.kind==='video'?'<button class="secondary" data-a="camera-silent">Rekam tanpa mikrofon</button>':''}<small>Buka langsung di Safari atau Chrome melalui alamat HTTPS.</small></div>`;S.cameraReady=false}
async function mountCamera(){const box=$('#camera-box'),stream=S.stream;if(!box||!stream)return false;S.cameraReady=false;box.innerHTML=`<video id="camera-live" muted autoplay playsinline webkit-playsinline class="${S.mirror?'mirrored':''}"></video><div class="camera-overlay ${S.light?'lit':''}"></div><div class="pose-guide" id="pose-guide">${S.kind==='video'?clipGuide():'Pose 1 · Senyum dulu, ya.'}</div>`;const v=$('#camera-live');v.style.filter=ui.filters[S.filter];const ready=await PixCamera.attach(v,stream);if(S.stream!==stream||!v.isConnected)return false;S.cameraReady=ready;if(ready){box.style.setProperty('--camera-ratio',v.videoWidth+' / '+v.videoHeight);setCameraStatus('● Kamera siap · tampilan utuh');return true}setCameraStatus('Sentuh untuk menampilkan kamera');const button=document.createElement('button');button.className='primary camera-resume';button.dataset.a='camera-resume';button.textContent='Tampilkan kamera';box.append(button);return false}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
function beep(freq=750){try{const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;g.gain.value=.045;o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+.1);o.onended=()=>ac.close()}catch{}}
async function countdown(){for(let i=S.delay;i>0;i--){if(!S.busy)return false;let el=$('#count');if(!el){el=document.createElement('div');el.id='count';el.className='camera-count';$('#camera-box').append(el)}el.textContent=i;beep();await pause(1000)}$('#count')?.remove();return S.busy}
async function capture(){if(S.busy){S.busy=false;$('#count')?.remove();toast('Pengambilan dihentikan.');return}if(S.recording){S.recorder.stop();return}if(!S.stream)await openCamera();if(!S.cameraReady)throw new Error('Pratinjau kamera belum siap. Tekan Tampilkan kamera atau coba buka lagi.');if(S.kind==='video')return recordVideo();S.busy=true;const count=Math.min(S.kind==='motion'?4:S.poses,5-S.media.length);if(count<=0){S.busy=false;throw new Error('Bahan sudah penuh. Hapus salah satu dahulu.')}try{for(let i=0;i<count;i++){const guide=$('#pose-guide');if(guide)guide.textContent=['Senyum dulu, ya.','Peace bersama bestie.','Coba ekspresi paling lucu.','Pose favoritmu!'][i%4];if(!await countdown())break;const c=document.createElement('canvas'),v=$('#camera-live');PixCamera.captureFrame(c,v,S.mirror);beep(1100);await addMedia(await new Promise(r=>c.toBlob(r,'image/jpeg',.96)),'image');await pause(300)}}finally{S.busy=false;$('#count')?.remove()}}
async function recordVideo(){if(!S.cameraReady)throw new Error('Kamera belum siap.');if(S.media.length>=5)throw new Error('Maksimal lima klip.');if(!window.MediaRecorder)throw new Error('Browser belum mendukung perekaman. Gunakan unggahan video.');const mime=['video/mp4','video/webm;codecs=vp8,opus','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw new Error('Format rekaman tidak tersedia. Gunakan galeri.');const chunks=[],rec=new MediaRecorder(S.stream,{mimeType:mime,videoBitsPerSecond:6000000});const startedAt=performance.now();rec.onerror=()=>{S.recording=false;clearInterval(S.recordTicker);toast('Rekaman gagal. Klip sebelumnya tetap tersedia.');};S.recorder=rec;S.recording=true;$('.shutter').classList.add('recording');rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=async()=>{clearInterval(S.recordTicker);S.recording=false;$('.shutter')?.classList.remove('recording');$('#record-label')?.remove();try{await addMedia(new Blob(chunks,{type:mime.split(';')[0]}),'video',Math.min(10,(performance.now()-startedAt)/1000));toast('Klip ditambahkan. '+clipGuide())}catch(e){toast(e.message)}};rec.start(250);let secs=0;const label=document.createElement('div');label.className='record-label';label.id='record-label';label.textContent='● 00:00 / 00:10';$('#camera-box').append(label);S.recordTicker=setInterval(()=>{secs++;label.textContent='● 00:'+String(secs).padStart(2,'0')+' / 00:10';if(secs>=10&&rec.state==='recording')rec.stop()},1000)}
async function uploadMedia(file){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/assets');xhr.withCredentials=true;xhr.timeout=120000;xhr.setRequestHeader('Content-Type',file.type.split(';')[0]);xhr.upload.onprogress=e=>{const label=$('#upload-progress');if(label&&e.lengthComputable)label.textContent='Mengunggah '+Math.round(e.loaded/e.total*100)+'%'};xhr.onerror=()=>reject(new Error('Koneksi terputus. Bahan tetap di halaman ini; coba lagi.'));xhr.ontimeout=()=>reject(new Error('Unggahan terlalu lama. Periksa jaringan lalu coba lagi.'));xhr.onload=()=>{let d;try{d=JSON.parse(xhr.responseText)}catch{return reject(new Error('Server tidak merespons unggahan.'))}if(xhr.status<200||xhr.status>=300)reject(new Error(d.error||'Unggahan gagal.'));else resolve(d.id)};xhr.send(file)})}
async function generate(){if(S.kind==='photo'&&(S.event.type==='running'||['preston-fest','scream-or-dance'].includes(S.event.id))&&S.media.length<(activeDesigns().find(d=>d.id===activeDesign())?.photos||1))throw new Error('Lengkapi jumlah foto untuk desain yang dipilih terlebih dahulu.');if(S.busy)throw new Error('Tunggu pengambilan foto selesai.');if(S.recording)throw new Error('Hentikan rekaman terlebih dahulu.');if(!S.media.length)throw new Error('Ambil atau pilih setidaknya satu foto/klip dahulu.');if(S.kind==='video'&&S.media.filter(m=>m.type==='video').reduce((n,m)=>n+m.duration,0)<S.filmDuration*.5)throw new Error('Tambahkan klip: untuk film '+S.filmDuration+' detik, rekaman minimal '+S.filmDuration/2+' detik.');if(!S.consent)throw new Error('Setujui pemrosesan dan penyimpanan media terlebih dahulu.');if(customerPrice()&&!(S.payment?.status==='paid'&&S.payment.eventId===S.event.id&&S.payment.kind===S.kind&&!S.payment.used)){await checkout();return}stopStream();S.busy=true;let btn=$('[data-a="generate"]');btn.disabled=true;S.requestId??=crypto.randomUUID();try{btn.textContent='Menyiapkan media…';let ids=[],overlay;
if(S.kind==='photo'){const c=document.createElement('canvas');c.width=1080;c.height=1920;paint(c);const blob=await new Promise(r=>c.toBlob(r,'image/png'));ids.push(await uploadMedia(blob))}else{for(let i=0;i<S.media.length;i++){btn.textContent=`Mengunggah bahan ${i+1}/${S.media.length}…`;ids.push(await uploadMedia(S.media[i].blob))}const c=document.createElement('canvas');c.width=1080;c.height=1920;paint(c,true);overlay=await uploadMedia(await new Promise(r=>c.toBlob(r,'image/png')))}
const job=await api('/api/jobs',{requestId:S.requestId,filmDuration:S.filmDuration,motionDesign:S.motionDesign,eventId:S.event.id,kind:S.kind,assets:ids,overlay,template:S.template,music:S.music,keepAudio:S.keepAudio,filter:S.filter,design:S.frame,videoDesign:S.videoDesign,caption:S.caption,orderId:S.payment?.id});if(S.payment)S.payment.used=true;jobInfo={id:job.id,key:job.key,eventId:S.event.id};safeStore('pixbooth-last-result',JSON.stringify(jobInfo));S.requestId=null;S.busy=false;history.pushState({},'','/hasil?id='+job.id+'#'+job.key);currentPath='/hasil';showResult(job)}catch(e){S.busy=false;btn.disabled=false;btn.textContent=S.kind==='photo'?'Buat foto Story ↗':'Buat video otomatis ↗';throw e}}
function resultUrl(download=false){return '/result/'+jobInfo.id+'?key='+encodeURIComponent(jobInfo.key)+(download?'&download=1':'')}
async function restoreResult(){const params=new URLSearchParams(location.search);if(params.has('id')&&location.hash.length>1){jobInfo={id:params.get('id'),key:location.hash.slice(1)}}else{try{jobInfo=JSON.parse(localStorage.getItem('pixbooth-last-result'))}catch{}}if(!jobInfo)return missing();try{const job=await api('/api/jobs/'+jobInfo.id+'?key='+jobInfo.key);S.event=S.events.find(e=>e.id===job.eventId)||{name:'Kenanganmu',type:'concert'};showResult(job)}catch(e){app.innerHTML=`<div class="page"><h1>Hasil belum tersedia.</h1><p class="muted">${esc(e.message)}</p><button class="primary" data-a="reload">Periksa lagi</button></div>`;if(![404,410].includes(e.status))jobPoll=setTimeout(restoreResult,5000)}}
function showResult(job){clearTimeout(jobPoll);jobPoll=null;$('#toast').classList.remove('visible');cancelAnimationFrame(previewRaf);document.body.className='event-app '+S.event.type;const ready=job.status==='ready',failed=job.status==='failed';app.innerHTML=`${eventHeader()}<main class="event-shell"><div class="result-layout"><div>${ready?(job.kind==='photo'?`<img class="result-file" src="${resultUrl()}" alt="Hasil foto Story">`:`<video class="result-file" src="${resultUrl()}" controls playsinline></video>`):`<div class="studio-preview" style="background:#ffffff06;border-color:#ffffff15;min-height:450px"><div class="${failed?'success-icon':'process-orb'}">${failed?'!':''}</div><p class="muted">${failed?'Proses belum berhasil':'Momenmu sedang dirangkai'}</p></div>`}</div><div class="result-copy"><span class="eyebrow">${ready?'A MOMENT TO KEEP':'YOUR STORY IS ON ITS WAY'}</span><h1>${ready?'Kenanganmu,<br>siap dibawa pulang.':failed?'Kita coba lagi.':'Sedang merangkai<br>ceritamu.'}</h1><p>${ready?'Simpan hasilnya, lalu pilih melalui galeri saat membuat Instagram Story. Kontenmu tidak diposting otomatis.':failed?esc(job.error):'Kamu boleh menutup halaman ini dan kembali melalui tautan hasil. Proses berjalan di server aplikasi.'}</p>${!ready&&!failed?`<div class="job-progress"><span style="width:${job.progress||0}%"></span></div><p>${job.status==='queued'?'Menunggu giliran':job.progress<75?'Menyiapkan dan menyusun klip':'Menambahkan bingkai dan audio'} · ${job.progress||0}%</p>`:''}<div class="studio-actions">${ready?`<a class="primary" href="${resultUrl(true)}">↓ Simpan ${job.kind==='photo'?'PNG':'MP4'}</a><button class="secondary" data-a="share-result">Bagikan</button>`:''}<button class="secondary" data-a="back-event">${failed?'Kembali ke studio':'Buat hasil lain'}</button></div>${ready&&job.kind==='motion'?`<a class="secondary" href="${resultUrl(true)}&format=gif">↓ Simpan GIF (540 × 960)</a><p class="micro">Untuk Instagram Story gunakan MP4. GIF tersedia sebagai pilihan tambahan.</p>`:''}${ready?`<p>1080 × 1920 · ${job.duration?job.duration+' detik · ':''}${(job.bytes/1024/1024).toFixed(1)} MB<br>Tersedia sampai ${new Date(job.expires).toLocaleString('id-ID')}</p><button class="text-button" data-a="copy-result">Salin tautan pribadi ↗</button><p class="micro">Tautan memberi akses ke hasilmu. Bagikan hanya kepada orang yang kamu pilih.</p>`:''}</div></div></main>`;if(!ready&&!failed)jobPoll=setTimeout(async()=>{try{showResult(await api('/api/jobs/'+jobInfo.id+'?key='+jobInfo.key))}catch(e){toast('Koneksi belum stabil. Memeriksa hasil lagi…');jobPoll=setTimeout(()=>restoreResult(),5000)}},2000)}
async function loadPortal(){document.body.className='';const {user}=await api('/api/session');const permitted=currentPath==='/admin'?['owner','operator']:currentPath==='/mitra'?['partner']:['owner','finance'];if(!user)return loginPage();if(!permitted.includes(user.role)){app.innerHTML=`<div class="page">${brand()}<h1>Akses tidak diizinkan.</h1><p class="muted">Akun ini tidak memiliki akses ke portal tersebut.</p><button class="secondary" data-a="logout">Keluar dari akun</button></div>`;return}S.dash=await api('/api/dashboard');const requestedEvent=new URLSearchParams(location.search).get('event');if(currentPath==='/mitra'&&requestedEvent&&!S.dash.events.some(e=>e.id===requestedEvent)){app.innerHTML=`<div class="page"><h1>Akun ini untuk acara lain.</h1><p class="muted">Akses akunmu hanya untuk ${esc(S.dash.events[0]?.name||'acara yang ditetapkan')}. Masuk dengan akun acara yang sesuai.</p><button class="primary" data-a="logout">Keluar & ganti akun</button></div>`;return}portal()}
function loginPage(){const name={'/admin':'Administrasi','/mitra':'Mitra','/keuangan':'Keuangan'}[currentPath];app.innerHTML=`<div class="portal-login"><aside class="login-aside"><span class="brand">pixbooth.</span><div><span class="eyebrow">${name.toUpperCase()} WORKSPACE</span><h1>Di balik setiap<br><em>kenangan baik.</em></h1><p>Ruang kerja khusus untuk mengelola pengalaman PixBooth dengan akses sesuai tanggung jawab.</p></div><span class="micro">Akses khusus · Bukan halaman pengunjung</span></aside><main class="login-main"><div class="login-card"><span class="eyebrow">PORTAL ${name.toUpperCase()}</span><h2>Selamat datang kembali.</h2><p class="muted">${currentPath==='/mitra'?'Satu akun khusus satu acara. '+esc(S.events.find(e=>e.id===new URLSearchParams(location.search).get('event'))?.name||'Gunakan akun acara yang diberikan.'):'Masuk menggunakan akun yang diberikan perusahaan.'}</p><form id="login-form" class="stack-form"><label for="login-email">Email</label><input type="email" id="login-email" name="email" autocomplete="username" required><label for="login-password">Kata sandi</label><input type="password" id="login-password" name="password" autocomplete="current-password" required><div class="form-error" id="login-error" role="alert"></div><button class="primary full-width" type="submit">Masuk ke workspace ↗</button></form><p class="micro">Akun lokal disediakan dalam file akses terpisah. Tidak ditampilkan di halaman publik.</p></div></main></div>`}
function statCards(items){return `<div class="stats">${items.map(([label,value,note])=>`<div class="stat"><small>${label}</small><strong>${value}</strong><span class="neutral">${note}</span></div>`).join('')}</div>`}
function portal(){const d=S.dash,r=d.user.role,isPartner=r==='partner',isFinance=currentPath==='/keuangan',owner=r==='owner',menus=isPartner?['Ringkasan','Acara saya','Analitik acara','Tagihan','Permintaan']:isFinance?['Ringkasan','Transaksi & tagihan','Biaya & hasil','Laporan']:['Ringkasan','Semua acara','Template','Antrean & hasil','Pengajuan mitra',...(owner?['Biaya & hasil','Hak akses','Jejak aktivitas']:[])];if(!menus.includes(S.tab))S.tab='Ringkasan';app.innerHTML=`<header class="portal-head">${brand(currentPath)}<div class="portal-links"><small>${esc(d.user.name)} · ${r==='owner'?'Pemilik':r==='partner'?'Mitra':r==='operator'?'Operasional':'Keuangan'}</small><button class="secondary" data-a="refresh-dash">↻ Perbarui</button><button class="secondary" data-a="logout">Keluar</button></div></header><div class="dashboard"><aside class="sidebar"><div class="workspace-label">${isPartner?'PARTNER':isFinance?'FINANCE':'COMPANY'} WORKSPACE</div><nav class="side-nav">${menus.map((m,i)=>`<button class="${S.tab===m?'active':''}" data-tab="${m}"><span>${['◫','▦','✧','◈','◇','◎'][i%6]}</span>${m}</button>`).join('')}</nav><div class="access-note">Data tersimpan pada server lokal.<br><br>Hak akses diperiksa server pada setiap permintaan.</div></aside><main><div class="dash-top"><div><span class="eyebrow">${isPartner?'YOUR EVENTS, YOUR SPACE':isFinance?'FINANCIAL WORKSPACE':'BEHIND THE MOMENTS'}</span><h1>${S.tab==='Ringkasan'?'Halo, '+esc(d.user.name)+'.':S.tab}</h1><p>${isPartner?'Kelola satu acara yang ditetapkan untuk akun ini.':isFinance?'Pencatatan tagihan dan pembayaran manual.':'Kelola acara, layanan, dan kebutuhan mitra.'}</p></div>${!isPartner&&!isFinance?'<button class="primary" data-a="new-event">+ Buat acara</button>':isFinance?'<button class="primary" data-a="new-invoice">+ Buat tagihan</button>':''}</div><div class="portal-notice">Versi pengembangan lokal. Seluruh acara merupakan contoh; jumlah hasil dan tagihan mengikuti aktivitas nyata di aplikasi ini. Checkout pelanggan menggunakan simulasi tanpa uang sungguhan.</div>${portalContent(d,isPartner,isFinance,owner)}</main></div>`;document.querySelectorAll('[data-portal-design]').forEach(c=>{const t=PixDesign.catalog.find(t=>t.id===c.dataset.portalDesign),event=d.events.find(e=>e.id===t.eventId)||d.events.find(e=>e.type===t.type)||{name:'Nama acaramu',type:t.type,location:'Lokasi acara'};PixDesign.render(c,{design:t.id,event,kind:'photo',poses:4})})}
function eventCards(d,partner){return d.events.map(e=>`<article class="portal-event-card"><div class="panel-head"><div><h3>${esc(e.name)}</h3><span class="pill ${e.status==='active'?'':'pending'}">${e.status==='active'?'Aktif':e.status==='draft'?'Draft':'Ditutup'}</span></div><span class="badge">${e.type.toUpperCase()}</span></div><p>${esc([e.location,e.date].filter(Boolean).join(" · "))}<br>${esc(e.plan)} · ${e.used} / ${e.quota} hasil · Simpan ${e.retention} jam</p><div class="studio-actions"><a class="secondary" href="/e/${e.id}" target="_blank" rel="noopener">Buka halaman ↗</a><button class="secondary" data-qr="${e.id}">QR & tautan</button><button class="secondary" ${partner?'data-request':'data-edit-event'}="${e.id}">${partner?'Ajukan kebutuhan':'Pengaturan'}</button></div></article>`).join('')||'<div class="empty-data">Belum ada acara.</div>'}
function invoiceTable(d,partner){return ordersTable(d)+`<div class="panel portal-panel"><div class="panel-head"><h3>Tagihan kerja sama</h3>${!partner?'<button class="text-button" data-a="new-invoice">+ Buat tagihan</button>':''}</div>${d.invoices.length?`<div class="table-wrap"><table class="portal-table"><thead><tr><th>NOMOR</th><th>ACARA</th><th>NILAI</th><th>STATUS</th>${!partner?'<th>TINDAKAN</th>':''}</tr></thead><tbody>${d.invoices.map(i=>`<tr><td>${i.id}</td><td>${esc(d.events.find(e=>e.id===i.eventId)?.name||i.eventId)}</td><td>${money(i.amount)}</td><td><span class="pill ${i.status==='paid'?'':'pending'}">${i.status==='paid'?'Lunas (manual)':'Belum lunas'}</span></td>${!partner?`<td><button class="row-button" data-invoice="${i.id}" data-status="${i.status==='paid'?'unpaid':'paid'}">${i.status==='paid'?'Batalkan pencatatan':'Catat pembayaran'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty-data">Belum ada tagihan.<br>Tidak ada transaksi atau saldo fiktif.</div>'}</div>`}
function jobsTable(d){return `<div class="panel portal-panel"><h3>Antrean & hasil</h3>${d.jobs.length?`<div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>ACARA</th><th>FORMAT</th><th>STATUS</th></tr></thead><tbody>${d.jobs.slice(0,40).map(j=>`<tr><td>${new Date(j.created).toLocaleString('id-ID')}</td><td>${esc(j.eventId)}</td><td>${j.kind}</td><td><span class="pill ${j.status==='ready'?'':'pending'}">${j.status==='processing'?j.progress+'%':j.status}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-data">Belum ada hasil. Coba kamera atau unggah media melalui halaman acara.</div>'}<p class="micro">Tautan foto/video pribadi tidak ditampilkan kepada mitra atau staf.</p></div>`}
function portalContent(d,partner,finance,owner){if(S.tab==='Acara saya'||S.tab==='Semua acara')return `<div class="portal-panel">${eventCards(d,partner)}</div>`;if(['Tagihan','Transaksi & tagihan'].includes(S.tab))return invoiceTable(d,partner);if(S.tab==='Antrean & hasil')return jobsTable(d);if(S.tab==='Template')return `<div class="panel portal-panel"><h3>Library desain pengalaman</h3><p class="muted">${PixDesign.catalog.length} desain foto dengan komposisi dan identitas acara berbeda, delapan konsep film, dan dua desain motion. Nama acara diambil otomatis dari pengaturannya.</p><div class="template-overview">${PixDesign.catalog.map(t=>`<article><canvas width="216" height="384" data-portal-design="${t.id}" style="width:100%;height:auto;max-height:330px;object-fit:contain" aria-label="Desain ${t.name}"></canvas><h4>${t.name}</h4><p>${t.tag}</p><span class="badge">${t.type.toUpperCase()}</span></article>`).join('')}</div><p class="muted">Foto, GIF, dan film memakai desain terpisah. Film 60 detik berisi 12 babak dengan opening, split screen, zoom, highlight, serta closing.</p></div>`;
if(S.tab==='Permintaan')return `<div class="panel portal-panel"><h3>Permintaanmu</h3>${d.requests.length?d.requests.map(r=>`<div class="event-row"><div><b>${esc(r.eventId)}</b><p>${esc(r.note)}</p><small>${new Date(r.at).toLocaleString('id-ID')}</small></div><span class="pill pending">Diterima</span></div>`).join(''):'<div class="empty-data">Belum ada permintaan. Ajukan melalui acara yang ingin diubah.</div>'}</div>`;
if(S.tab==='Pengajuan mitra')return `<div class="panel portal-panel"><h3>Pengajuan dari website promosi</h3>${d.inquiries.length?d.inquiries.map(i=>`<div class="event-row"><div><b>${esc(i.name)} · ${esc(i.type)}</b><p>${esc(i.contact)}<br>${esc(i.note)}</p><small>${new Date(i.at).toLocaleString('id-ID')}</small></div></div>`).join(''):'<div class="empty-data">Belum ada pengajuan.</div>'}<h3 style="margin-top:25px">Permintaan mitra terdaftar</h3>${d.requests.map(r=>`<div class="event-row"><div><b>${esc(r.eventId)}</b><p>${esc(r.note)}</p><small>${esc(r.email)}</small></div></div>`).join('')||'<p class="muted">Belum ada permintaan.</p>'}</div>`;
if(S.tab==='Hak akses')return `<div class="panel portal-panel"><div class="panel-head"><h3>Pembatasan akses aktif</h3><button class="text-button" data-a="new-account">+ Tambah akun</button></div><div class="permission-grid">${[['Pemilik','Seluruh acara, tagihan, pengajuan, dan jejak aktivitas.'],['Operasional','Acara, template, proses, serta pengajuan. Tidak boleh membuat atau menandai tagihan.'],['Keuangan','Tagihan, laporan dan pencatatan pembayaran manual. Tidak boleh mengubah acara.'],['Mitra','Hanya acara miliknya, kuota, QR, tagihan miliknya, dan permintaan.']].map(([n,t])=>`<div class="permission"><b>${n}</b><p>${t}</p></div>`).join('')}</div><h3 style="margin-top:25px">Akun terdaftar</h3>${d.accounts.map(a=>`<div class="event-row"><div><b>${esc(a.name)}</b><small>${esc(a.email)}</small></div><span class="badge">${a.role}</span></div>`).join('')}<p class="muted">Kata sandi disimpan sebagai hash. Setiap akun mitra terikat pada satu acara. Buat akun mitra baru dengan memilih acara; akses akun sebelumnya pada acara itu akan berakhir.</p></div>`;
if(S.tab==='Jejak aktivitas')return `<div class="panel portal-panel"><h3>Aktivitas pengelolaan</h3><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>AKUN</th><th>AKTIVITAS</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td>${new Date(a.at).toLocaleString('id-ID')}</td><td>${esc(a.actor)}</td><td>${esc(a.action)} · ${esc(a.target)}</td></tr>`).join('')}</tbody></table></div></div>`;
if(S.tab==='Laporan')return `<div class="panel portal-panel"><h3>Laporan keuangan</h3><p class="muted">Ekspor tagihan yang tercatat di aplikasi lokal. Status lunas berasal dari pencatatan manual, bukan verifikasi bank.</p><button class="primary" data-a="export">↓ Unduh CSV</button></div>`;
const ready=d.jobs.filter(j=>j.status==='ready').length,pending=d.jobs.filter(j=>['queued','processing'].includes(j.status)).length;return finance?`${statCards([['Pembayaran tercatat',money(d.invoices.filter(i=>i.status==='paid').reduce((s,i)=>s+i.amount,0)),'Pencatatan manual'],['Tagihan terbuka',money(d.invoices.filter(i=>i.status!=='paid').reduce((s,i)=>s+i.amount,0)),'Belum lunas'],['Jumlah tagihan',d.invoices.length,'Data tersimpan lokal']])}${invoiceTable(d,false)}`:`${statCards([['Acara aktif',d.events.filter(e=>e.status==='active').length,'Dalam cakupan akun'],['Hasil selesai',ready,'Foto & video sebenarnya'],[partner?'Sisa kuota':'Dalam antrean',partner?d.events.reduce((s,e)=>s+Math.max(0,e.quota-e.used),0):pending,partner?'Seluruh acara milikmu':'Diproses otomatis']])}<div class="portal-panel">${eventCards(d,partner)}</div>${jobsTable(d)}`}
function eventOptions(){return S.dash.events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}
function newEvent(){info('Buat pengalaman baru',`<form id="new-event-form" class="stack-form"><label>Nama acara<input name="name" required maxlength="80"></label><label>Alamat halaman<input name="id" required pattern="[a-z0-9-]+" placeholder="contoh: music-night"></label><label>Jenis<select name="type"><option value="concert">Konser</option><option value="tourism">Wisata</option><option value="wedding">Wedding</option><option value="running">Lari / olahraga</option></select></label><label>Lokasi<input name="location" maxlength="80"></label><label>Tanggal<input type="date" name="date"></label><label>Model paket<select name="plan"><option value="sponsored">Ditanggung penyelenggara</option><option value="hybrid">Foto gratis, video berbayar</option><option value="paid">Semua hasil berbayar</option></select></label><label>Kuota hasil<input type="number" name="quota" min="1" max="100000" value="100"></label><label>Sponsor<input name="sponsor" maxlength="80"></label><p class="micro">Dibuat sebagai draft. Aktifkan setelah memeriksa pengaturan. Subdomain produksi belum dikonfigurasi.</p><button class="primary">Simpan draft ↗</button></form>`)}
function editEvent(eventId){const e=S.dash.events.find(e=>e.id===eventId);info('Pengaturan acara',`<form id="edit-event-form" class="stack-form" data-id="${eventId}"><label>Nama<input name="name" required value="${esc(e.name)}"></label><label>Status<select name="status">${[['draft','Draft'],['active','Aktif'],['closed','Ditutup']].map(([v,n])=>`<option value="${v}" ${e.status===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Paket<select name="plan">${[['sponsored','Ditanggung penyelenggara'],['hybrid','Foto gratis, video berbayar'],['paid','Semua hasil berbayar']].map(([v,n])=>`<option value="${v}" ${e.plan===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Kuota<input name="quota" type="number" min="${e.used}" max="100000" value="${e.quota}"></label>${S.dash.user.role==='owner'?`<label>Akun mitra<select name="partner">${S.dash.accounts.filter(a=>a.role==='partner'&&a.eventId===e.id).map(a=>`<option value="${esc(a.email)}" ${a.email===e.partner?'selected':''}>${esc(a.name)} · ${esc(a.email)}</option>`).join('')}</select></label>`:''}<label class="toggle-line"><span>Izinkan unggah dari galeri</span><input name="allowUpload" type="checkbox" ${e.allowUpload?'checked':''} style="width:auto"></label><button class="primary">Simpan perubahan</button></form>`)}
function newInvoice(){info('Buat tagihan kerja sama',`<form id="invoice-form" class="stack-form"><label>Acara<select name="eventId">${eventOptions()}</select></label><label>Nominal (Rp)<input name="amount" type="number" min="1" required></label><label>Keterangan<input name="note" maxlength="200" placeholder="Paket acara / tambahan kuota"></label><p class="micro">Ini pencatatan tagihan lokal. Tidak mengirim tagihan atau menarik uang.</p><button class="primary">Buat tagihan</button></form>`)}
function qrInfo(eventId){const e=S.dash.events.find(e=>e.id===eventId),link=location.origin+'/e/'+eventId;info('QR pengalamanmu',`<div class="qr-print"><h3>${esc(e.name)}</h3><p class="muted">Scan. Buat momen. Bawa pulang kenangan.</p><img class="qr-img" src="/api/qr/${eventId}" alt="QR akses acara"><a href="${link}" target="_blank" rel="noopener">${esc(link)}</a><p class="micro">Alamat localhost hanya dapat dibuka di komputer ini. QR untuk pengunjung lokasi memerlukan deployment HTTPS.</p></div><div class="info-actions"><a class="primary" href="/api/qr/${eventId}?download=1">↓ Unduh QR SVG</a><button class="secondary" data-a="print">Cetak materi</button><button class="secondary" data-copy="${link}">Salin tautan</button></div>`)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Tautan disalin.')}catch{info('Salin tautan',`<input class="form-input" readonly value="${esc(text)}"><p class="muted">Pilih lalu salin alamat di atas.</p>`)}}
async function openLdr(){stopStream();cancelAnimationFrame(previewRaf);S.busy=false;const params=new URLSearchParams(location.search),joining=params.has('room');document.body.className='event-app '+S.event.type;app.innerHTML=`${eventHeader()}<main class="event-shell"><span class="eyebrow">FAR APART, SAME FRAME</span><div class="event-welcome"><div><h1>Jauh tempatnya.<br>Dekat di kenangannya.</h1><p>Buat ruang privat untuk dua orang. Sambungkan kamera, lalu foto dalam satu bingkai.</p></div><button class="secondary" data-a="leave-ldr">Kembali ke photobox</button></div><section class="ldr-room"><div class="tag-row"><span class="badge">LDR PHOTOBOX</span><span class="muted" id="ldr-status">${joining?'Siap bergabung':'Siap membuat ruang'}</span></div><div class="ldr-streams"><div><video id="ldr-local" muted autoplay playsinline></video><span>Kamu</span></div><div><video id="ldr-remote" autoplay playsinline muted></video><span>Temanmu</span></div></div><div class="studio-actions"><button class="primary" data-a="${joining?'join-ldr':'create-ldr'}">${joining?'Gabung & buka kamera':'Buat ruang & buka kamera'} ↗</button><button class="secondary" data-a="ldr-capture" disabled>◎ Foto berdua</button></div><div id="ldr-invite"></div><div class="status-strip">Koneksi memakai WebRTC dengan ruang privat di server. Gunakan tautan HTTPS publik yang sama untuk dua HP. STUN sudah dikonfigurasi; beberapa jaringan seluler memerlukan server relay TURN. Pada localhost tautan belum dapat dibuka dari HP lain.</div></section></main>`}
async function roomPost(type,data){const r=S.room;if(!r)return;return apiRoom('/api/rooms/'+r.roomId,{type,data})}
async function apiRoom(url,body){const r=S.room,res=await fetch(url,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Room-Key':r.secret,'X-Participant':r.participant||''},body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok)throw new Error(data.error);return data}
async function connectLdr(join){if(S.room)return;if(!navigator.mediaDevices?.getUserMedia)throw new Error('Kamera LDR memerlukan HTTPS dan browser yang mendukung kamera.');S.stream=await PixCamera.request(navigator.mediaDevices,'user',false);if(!await PixCamera.attach($('#ldr-local'),S.stream)){stopStream();throw new Error('Pratinjau LDR belum siap. Coba buka kembali ruang.')}try{if(join){const p=new URLSearchParams(location.search);S.room={roomId:p.get('room'),secret:location.hash.slice(1),participant:null,seq:0,host:false};const joined=await apiRoom('/api/rooms/'+S.room.roomId+'/join',{});S.room.participant=joined.participant}else S.room={...await api('/api/rooms',{}),seq:0,host:true};const r=S.room;const pc=new RTCPeerConnection(await apiRoom('/api/rtc-config'));r.pc=pc;r.pendingIce=[];S.stream.getTracks().forEach(t=>pc.addTrack(t,S.stream));pc.ontrack=async e=>{const ready=await PixCamera.attach($('#ldr-remote'),e.streams[0]);$('[data-a="ldr-capture"]').disabled=!ready;$('#ldr-status').textContent=ready?'● Terhubung. Siap satu frame.':'Video pasangan belum siap. Coba sambung kembali.'};pc.onicecandidate=e=>{if(e.candidate)roomPost('ice',e.candidate.toJSON()).catch(()=>{})};pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(pc.connectionState))$('#ldr-status').textContent='Koneksi terputus. Jaringan ini mungkin memerlukan TURN.'};const button=$('[data-a="'+(join?'join-ldr':'create-ldr')+'"]');button.disabled=true;button.textContent='Kamera aktif';if(!join){const invite=location.origin+'/e/'+S.event.id+'?room='+r.roomId+'#'+r.secret;$('#ldr-invite').innerHTML=`<div class="ldr-link"><input class="form-input" readonly value="${esc(invite)}"><button class="secondary" data-copy="${invite}">Salin undangan</button></div><p class="micro">Tautan privat berlaku satu jam. Berikan hanya kepada pasangan fotomu.</p>`;$('#ldr-status').textContent='Menunggu teman bergabung…'}else $('#ldr-status').textContent='Menghubungkan kamera…';pollRoom()}catch(e){stopStream();S.room=null;throw e}}
async function pollRoom(){const r=S.room;if(!r)return;try{const response=await apiRoom('/api/rooms/'+r.roomId+'?since='+r.seq);if(r.host&&response.members===2&&!r.offered){r.offered=true;const offer=await r.pc.createOffer();await r.pc.setLocalDescription(offer);await roomPost('offer',offer)}for(const m of response.messages){r.seq=Math.max(r.seq,m.seq);if(m.type==='offer'){await r.pc.setRemoteDescription(m.data);for(const c of r.pendingIce)await r.pc.addIceCandidate(c);r.pendingIce=[];const answer=await r.pc.createAnswer();await r.pc.setLocalDescription(answer);await roomPost('answer',answer)}if(m.type==='answer'){await r.pc.setRemoteDescription(m.data);for(const c of r.pendingIce)await r.pc.addIceCandidate(c);r.pendingIce=[]}if(m.type==='ice'){if(r.pc.remoteDescription)await r.pc.addIceCandidate(m.data);else r.pendingIce.push(m.data)}if(m.type==='capture')toast('Pasanganmu mengambil foto bersama.');if(m.type==='bye'){$('#ldr-status').textContent='Pasanganmu meninggalkan ruang.';$('[data-a="ldr-capture"]').disabled=true}}}catch(e){if($('#ldr-status'))$('#ldr-status').textContent=e.message}if(S.room===r)r.poll=setTimeout(pollRoom,850)}
function leaveRoom(){const r=S.room;if(!r)return;roomPost('bye',null).catch(()=>{});clearTimeout(r.poll);r.pc?.close();S.room=null;stopStream()}
async function captureLdr(){const local=$('#ldr-local'),remote=$('#ldr-remote');if(!local.videoWidth||!remote.videoWidth)throw new Error('Tunggu kedua kamera tersambung.');const c=document.createElement('canvas');c.width=1440;c.height=1920;const ctx=c.getContext('2d');ctx.fillStyle=ui.frames[S.frame][0];ctx.fillRect(0,0,1440,1920);drawCover(ctx,local,40,40,660,1840,true);drawCover(ctx,remote,740,40,660,1840);ctx.fillStyle='#fff';ctx.font='90px Georgia';ctx.textAlign='center';ctx.fillText('♡',720,970);await addMedia(await new Promise(r=>c.toBlob(r,'image/jpeg',.97)),'image');await roomPost('capture',{});toast('Foto berdua tersimpan. Kembali ke photobox untuk membuat Story.');}
async function refreshDash(){S.dash=await api('/api/dashboard');portal()}
function oldExportCsv(){const safe=s=>'"'+String(s??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';const rows=[['Nomor','Acara','Nominal','Status','Keterangan'],...S.dash.invoices.map(i=>[i.id,i.eventId,i.amount,i.status,i.note])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});saveBlob(blob,'PixBooth-Tagihan-Lokal.csv')}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
document.addEventListener('click',async ev=>{const anchor=ev.target.closest('a[data-nav]');if(anchor){ev.preventDefault();nav(anchor.getAttribute('href'));return}const b=ev.target.closest('button');if(!b)return;try{
if(b.dataset.experience){if(S.busy||S.recording)throw new Error('Selesaikan pengambilan foto atau rekaman sebelum mengganti template.');S.requestId=null;if(S.kind==='photo')S.frame=b.dataset.experience;else if(S.kind==='motion')S.motionDesign=b.dataset.experience;else S.videoDesign=b.dataset.experience;eventPage();return}if(b.dataset.checkoutOutcome){await finishCheckout(b.dataset.checkoutOutcome);return}if(b.dataset.kind){S.stage=1;S.requestId=null;if(S.busy||S.recording)throw new Error('Hentikan pengambilan terlebih dahulu.');const next=b.dataset.kind;if((S.kind==='video')!==(next==='video')&&S.media.length){info('Ganti jenis bahan?',`<p class="muted">${next==='video'?'Video membutuhkan klip rekaman.':'Mode ini memakai foto.'} Bahan yang sudah dipilih akan dikosongkan jika kamu melanjutkan.</p><div class="info-actions"><button class="secondary" data-a="close-info">Tetap di sini</button><button class="primary" data-confirm-kind="${next}">Ganti & mulai baru</button></div>`);return}stopStream();S.kind=next;eventPage();return}if(b.dataset.confirmKind){stopStream();S.media.forEach(m=>{m.element.pause?.();URL.revokeObjectURL(m.url)});S.media=[];S.kind=b.dataset.confirmKind;$('#info').close();eventPage();return}
for(const key of ['frame','layout','template','filter','sticker'])if(b.hasAttribute('data-'+key)){S[key]=b.getAttribute('data-'+key);document.querySelectorAll('[data-'+key+']').forEach(x=>x.classList.toggle('active',x.getAttribute('data-'+key)===S[key]));if(key==='filter'){S.requestId=null;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter===S.filter)));if($('#camera-live'))$('#camera-live').style.filter=ui.filters[S.filter];const status=$('#filter-status');if(status)status.textContent='Filter aktif: '+S.filter;paint($('#composition'));}if(key==='frame'){document.querySelectorAll('[data-frame]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.frame===S.frame)));const description=$('#design-description');if(description)description.textContent=PixDesign.catalog.find(d=>d.id===S.frame).tag;}refreshDesignPreviews();return}
if(b.hasAttribute('data-remove')){const removed=S.media.splice(Number(b.dataset.remove),1)[0];removed.element.pause?.();URL.revokeObjectURL(removed.url);renderTray();refreshDesignPreviews();return}
if(b.dataset.tab){S.tab=b.dataset.tab;portal();return}if(b.dataset.qr){qrInfo(b.dataset.qr);return}if(b.dataset.editEvent){editEvent(b.dataset.editEvent);return}if(b.dataset.request){info('Ajukan kebutuhan',`<form class="stack-form" id="request-form" data-id="${b.dataset.request}"><label>Kebutuhanmu<textarea name="note" required maxlength="2000" placeholder="Tambahan kuota atau perubahan desain…"></textarea></label><button class="primary">Kirim permintaan</button></form>`);return}if(b.dataset.invoice){const status=b.dataset.status;info(status==='paid'?'Catat pembayaran manual':'Batalkan pencatatan pembayaran',`<p class="muted">Tagihan <b>${b.dataset.invoice}</b> akan ditandai ${status==='paid'?'lunas berdasarkan pengecekanmu sendiri':'belum lunas'}. Aplikasi tidak memverifikasi rekening bank dan tidak memindahkan uang.</p><button class="primary" data-invoice-confirm="${b.dataset.invoice}" data-status="${status}">Konfirmasi pencatatan</button>`);return}if(b.dataset.invoiceConfirm){await api('/api/invoices/'+b.dataset.invoiceConfirm,{status:b.dataset.status},'PATCH');$('#info').close();await refreshDash();toast('Pencatatan diperbarui.');return}if(b.dataset.copy){await copy(b.dataset.copy);return}
switch(b.dataset.a){case'perunggu-reference':info('Referensi konser · Perunggu',`<p class="muted">33x — pemutar resmi, cuplikan 60 detik. Audio referensi ini terpisah dari file hasil. Film unduhan memakai musik PixBooth Original.</p><iframe title="Perunggu — 33x resmi" width="100%" height="280" src="https://www.youtube.com/embed/hbL5jQCw3As?start=0&end=60" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe>`);break;case'checkout-start':await startCheckout();break;case'checkout-generate':$('#info').close();await generate();break;case'close-info':$('#info').close();break;case'reload':location.reload();break;case'open-camera':await openCamera();break;case'camera-silent':await openCamera(false);break;case'camera-resume':{const v=$('#camera-live');if(v&&await PixCamera.resume(v)&&await PixCamera.ready(v)){S.cameraReady=true;$('.camera-resume')?.remove();setCameraStatus('● Kamera siap')}else cameraError(new Error('Pratinjau belum berjalan. Tutup aplikasi lain yang memakai kamera, lalu coba lagi.'));break}case'capture':await capture();break;case'flip':S.facing=S.facing==='user'?'environment':'user';S.mirror=S.facing==='user';if(S.stream)await openCamera();break;case'light':S.light=!S.light;$('.camera-overlay')?.classList.toggle('lit',S.light);toast(S.light?'Cahaya layar aktif.':'Cahaya layar nonaktif.');break;case'upload':$('#file-input').click();break;case'generate':await generate();break;case'ldr':if(S.media.some(m=>m.type==='video')){info('LDR menggunakan foto',`<p class="muted">Mulai sesi foto LDR? Klip video yang dipilih akan dikosongkan.</p><button class="primary" data-a="ldr-new-photo">Mulai sesi foto LDR</button>`);break}S.kind='photo';await openLdr();break;case'ldr-new-photo':S.media.forEach(m=>{m.element.pause?.();URL.revokeObjectURL(m.url)});S.media=[];S.kind='photo';$('#info').close();await openLdr();break;case'create-ldr':await connectLdr(false);break;case'join-ldr':await connectLdr(true);break;case'ldr-capture':await captureLdr();break;case'leave-ldr':leaveRoom();history.replaceState({},'',currentPath);S.kind='photo';S.stage=1;eventPage();break;case'back-event':S.stage=1;S.requestId=null;nav('/e/'+S.event.id);break;case'copy-result':await copy(location.origin+'/hasil?id='+jobInfo.id+'#'+jobInfo.key);break;case'share-result':{if(!navigator.share){toast('Simpan hasil lalu pilih dari galeri Instagram Story.');break}const blob=await(await fetch(resultUrl())).blob(),file=new File([blob],'PixBooth.'+(blob.type.startsWith('image/')?'png':'mp4'),{type:blob.type});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:S.event.name});else toast('Simpan hasil lalu pilih melalui galeri Instagram Story.');break}case'preview-music':if(S.audio&&!S.audio.paused){S.audio.pause();break}if(S.music==='none'){toast('Pilih musik contoh untuk mendengarkan.');break}S.audio=new Audio('/music.wav');await S.audio.play();toast('Memutar musik original contoh. Tekan lagi untuk berhenti.');break;case'logout':await api('/api/logout',{});safeStore('pixbooth-auth-updated',String(Date.now()));S.tab='Ringkasan';S.dash=null;loginPage();break;case'refresh-dash':await refreshDash();toast('Data diperbarui.');break;case'new-event':newEvent();break;case'new-account':info('Tambah akun workspace',`<form id="account-form" class="stack-form"><label>Nama<input name="name" required maxlength="80"></label><label>Email<input type="email" name="email" required></label><label>Peran<select name="role"><option value="partner">Mitra</option><option value="operator">Admin operasional</option><option value="finance">Keuangan</option></select></label><label>Acara khusus mitra<select name="eventId">${eventOptions()}</select></label><p class="micro">Untuk mitra, akun ini menggantikan akses mitra lama pada acara terpilih. Satu akun hanya untuk satu acara.</p><button class="primary">Buat akun</button></form>`);break;case'new-invoice':newInvoice();break;case'print':window.print();break;case'export':exportCsv();break}
}catch(e){if(e.name!=='AbortError')toast(e.message)}});
document.addEventListener('change',async ev=>{const t=ev.target;try{if(t.id==='file-input'){const files=[...t.files];if(files.length+S.media.length>5)throw new Error('Maksimal lima bahan.');for(const f of files){const video=S.kind==='video';if(f.size>(video?50:15)*1024*1024)throw new Error('File '+f.name+' melebihi batas ukuran.');if(video?!['video/mp4','video/webm','video/quicktime'].includes(f.type):!['image/jpeg','image/png','image/webp'].includes(f.type))throw new Error('Format '+f.name+' belum didukung.');await addMedia(f,video?'video':'image')}t.value=''}if(t.id==='consent')S.consent=t.checked;if(t.id==='poses'){S.poses=Number(t.value);const note=$('.capture-footer');if(note)note.textContent='Ambil '+S.poses+' pose dengan hitungan mundur. Kamu juga bisa mengganti foto satu per satu.';refreshDesignPreviews()}if(t.id==='delay')S.delay=Number(t.value);if(t.id==='music')S.music=t.value;if(t.id==='keep-audio')S.keepAudio=t.checked}catch(e){toast(e.message);t.value=''}});
document.addEventListener('input',ev=>{if(ev.target.id==='caption'){S.caption=ev.target.value;clearTimeout(S.captionRefresh);S.captionRefresh=setTimeout(refreshDesignPreviews,250)}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!['login-form','inquiry-form','new-event-form','edit-event-form','invoice-form','request-form','account-form'].includes(form.id))return;ev.preventDefault();const data=Object.fromEntries(new FormData(form));if(form.id==='login-form')data.eventId=new URLSearchParams(location.search).get('event')||undefined;const button=form.querySelector('button[type=submit],button.primary');if(button)button.disabled=true;try{if(form.id==='login-form'){await api('/api/login',data);safeStore('pixbooth-auth-updated',String(Date.now()));await loadPortal();return}if(form.id==='inquiry-form'){await api('/api/inquiries',data);form.reset();toast('Pengajuan tersimpan di aplikasi.');return}if(form.id==='account-form'){const account=await api('/api/accounts',data);$('#info').close();await refreshDash();info('Akun berhasil dibuat',`<p class="muted">Email: <b>${esc(account.email)}</b><br>Kata sandi: <b>${esc(account.password)}</b><br>Peran: ${esc(account.role)}</p><p class="muted">Simpan akses ini. Salinan juga ditambahkan ke file Akses-PixBooth-Lokal.txt. Tidak dikirim ke pihak lain.</p>`);return}if(form.id==='new-event-form'){await api('/api/manage/events',data);toast('Draft acara dibuat.')}if(form.id==='edit-event-form'){data.allowUpload=!!form.elements.allowUpload.checked;await api('/api/manage/events/'+form.dataset.id,data,'PATCH');toast('Pengaturan disimpan.')}if(form.id==='invoice-form'){await api('/api/invoices',data);toast('Tagihan dicatat.')}if(form.id==='request-form'){await api('/api/requests',{eventId:form.dataset.id,note:data.note});toast('Permintaan tersimpan.')}$('#info').close();await refreshDash()}catch(e){if(form.id==='login-form')$('#login-error').textContent=e.message;else toast(e.message)}finally{if(button)button.disabled=false}});
window.addEventListener('storage',event=>{if(event.key==='pixbooth-auth-updated'&&['/admin','/mitra','/keuangan'].includes(currentPath)){S.dash=null;S.tab='Ringkasan';loadPortal().catch(()=>loginPage())}});
window.addEventListener('beforeunload',()=>{stopStream();if(S.room){clearTimeout(S.room.poll);S.room.pc?.close()}});
