function customerPrice(){const e=S.event;if(e.prices)return e.plan==='sponsored'||(e.plan==='hybrid'&&S.kind==='photo')?0:e.prices[S.kind];return e.plan==='sponsored'||(e.plan==='hybrid'&&S.kind==='photo')?0:S.kind==='photo'?Math.round(e.price*.4):S.kind==='motion'?Math.round(e.price*.6):e.price}
async function checkout(){info('Checkout kenanganmu',`<div class="checkout-banner">MODE SIMULASI · Tidak menarik uang</div><div class="checkout-summary"><div class="event-logo">${PixExperience.logoSVG(S.event)}</div><h3>${S.kind==='video'?'Film pribadi 60 detik':S.kind==='motion'?'GIF + MP4 Motion':'Foto Story HD'}</h3><p>${esc(activeDesigns().find(d=>d.id===activeDesign()).name)} · 1080 × 1920</p><strong>${money(customerPrice())}</strong><p>Bayar sekali untuk satu hasil. Media tetap privat selama ${S.event.retention} jam.</p></div><label>Metode pembayaran contoh<select id="checkout-method"><option value="qris">QRIS</option><option value="va">Virtual Account</option><option value="ewallet">Dompet digital</option></select></label><p class="micro">Tidak perlu nomor rekening, data kartu, atau saldo. Pilih hasil simulasi pada langkah berikutnya.</p><button class="primary full-width" data-a="checkout-start">Lanjut ke simulasi pembayaran ↗</button>`)}
async function startCheckout(){const button=$('[data-a="checkout-start"]');button.disabled=true;try{S.payment=(await api('/api/checkout',{eventId:S.event.id,kind:S.kind,method:$('#checkout-method').value})).order;paymentScreen()}catch(e){button.disabled=false;throw e}}
function paymentScreen(){const o=S.payment;info('Pembayaran simulasi',`<div class="checkout-banner">SIMULASI · Tidak ada transaksi ke bank</div><div class="checkout-summary"><small>SIM-${o.id.slice(0,10).toUpperCase()}</small><h3>${money(o.amount)}</h3><div class="payment-placeholder">${o.method==='qris'?'▦ QRIS DEMO':o.method==='va'?'VA DEMO — 0000 0000':'DOMPET DIGITAL DEMO'}</div><p>Penanda tampilan saja. Jangan melakukan transfer.</p><small>Berlaku sampai ${new Date(o.expires).toLocaleTimeString('id-ID')}</small></div><div class="stack-form"><button class="primary" data-checkout-outcome="paid">Simulasikan pembayaran berhasil</button><button class="secondary" data-checkout-outcome="failed">Simulasikan pembayaran gagal</button><button class="text-button" data-checkout-outcome="cancelled">Batalkan transaksi</button></div>`)}
async function finishCheckout(outcome){document.querySelectorAll('[data-checkout-outcome]').forEach(b=>b.disabled=true);S.payment=(await api('/api/checkout/'+S.payment.id,{outcome})).order;if(outcome==='paid')info('Pembayaran simulasi berhasil',`<div class="checkout-banner">Tercatat sebagai simulasi · Rp0 ditarik</div><p>Pesanan SIM-${S.payment.id.slice(0,10).toUpperCase()} sudah siap untuk membuat satu hasil ${esc(S.event.name)}.</p><p class="muted">Tagihan contoh ${money(S.payment.amount)}. Statusnya terlihat di dashboard acara dan keuangan.</p><button class="primary full-width" data-a="checkout-generate">Buat hasil saya sekarang ↗</button>`);else info(outcome==='failed'?'Pembayaran simulasi gagal':'Transaksi dibatalkan',`<p class="muted">Tidak ada uang ditarik. Bahan yang kamu pilih tetap tersedia. Tekan buat hasil untuk mencoba checkout baru.</p><button class="primary" data-a="close-info">Kembali ke studio</button>`)}
function ordersTable(d){return `<section class="panel portal-panel"><h3>Pembayaran pelanggan · simulasi</h3><p class="micro">Nominal berikut bukan pendapatan atau saldo nyata. Satu pembayaran berhasil hanya dapat dipakai untuk satu hasil.</p>${d.orders?.length?`<div class="table-wrap"><table><thead><tr><th>PESANAN</th><th>ACARA</th><th>PAKET</th><th>NOMINAL</th><th>STATUS</th></tr></thead><tbody>${d.orders.slice(0,80).map(o=>`<tr><td>SIM-${o.id.slice(0,8)}</td><td>${esc(o.eventId)}</td><td>${esc(o.kind)} / ${esc(o.method)}</td><td>${money(o.amount)}</td><td><span class="pill ${o.status==='paid'?'':'pending'}">${esc(o.status)}${o.jobId?' · dipakai':''}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-data">Belum ada checkout pelanggan.</div>'}</section>`}
function exportCsv(){location.assign('/api/export/invoices.csv')}


document.addEventListener('visibilitychange',()=>{if(document.hidden&&!S.room){if(S.recorder?.state==='recording')S.recorder.stop();S.stream?.getTracks().forEach(t=>t.stop());S.stream=null;S.cameraReady=false;const label=$('#camera-state');if(label)label.textContent='Kamera dihentikan saat halaman di latar belakang. Buka kamera untuk melanjutkan.'}});
